-- ===========================================================================
-- Hand-written constraints (decision notes 0002, 0003, 0010, 0012).
-- Prisma's schema language cannot express these. They are covered by the SQL
-- tests in db/tests and must never be dropped silently.
-- ===========================================================================

-- IANA zone names only: the first segment may not contain "+" or "-", so
-- POSIX-style strings such as "UTC+3" are rejected even though PostgreSQL
-- accepts them in AT TIME ZONE.
CREATE FUNCTION flowwave_is_valid_time_zone(tz text) RETURNS boolean
LANGUAGE plpgsql IMMUTABLE STRICT AS $$
BEGIN
    IF char_length(tz) NOT BETWEEN 1 AND 64
       OR tz !~ '^[A-Za-z][A-Za-z0-9_]*(/[A-Za-z0-9_+-]+)*$' THEN
        RETURN false;
    END IF;
    PERFORM now() AT TIME ZONE tz;
    RETURN true;
EXCEPTION WHEN invalid_parameter_value THEN
    RETURN false;
END;
$$;

-- Explanations of calculated results must name their factors and carry the
-- non-medical disclaimer (project rules 2 and 10).
CREATE FUNCTION flowwave_is_valid_explanation(explanation jsonb) RETURNS boolean
LANGUAGE sql IMMUTABLE STRICT AS $$
    SELECT COALESCE(
        jsonb_typeof(explanation) = 'object'
        AND jsonb_typeof(explanation -> 'factors') = 'array'
        AND jsonb_typeof(explanation -> 'disclaimer') = 'string'
        AND char_length(explanation ->> 'disclaimer') > 0,
        false);
$$;

CREATE FUNCTION flowwave_set_updated_at() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
    NEW.updated_at_utc := now();
    RETURN NEW;
END;
$$;

-- users ---------------------------------------------------------------------
ALTER TABLE "users"
    ADD CONSTRAINT "users_home_time_zone_valid" CHECK (flowwave_is_valid_time_zone("home_time_zone")),
    ADD CONSTRAINT "users_sleep_goal_minutes_range" CHECK ("sleep_goal_minutes" BETWEEN 180 AND 900);

-- devices -------------------------------------------------------------------
ALTER TABLE "devices"
    ADD CONSTRAINT "devices_app_version_not_blank" CHECK ("app_version" IS NULL OR char_length("app_version") > 0);

-- consent_decisions (append-only) -------------------------------------------
ALTER TABLE "consent_decisions"
    ADD CONSTRAINT "consent_decisions_source_id_known" CHECK ("source_id" IN ('apple_health', 'health_connect')),
    ADD CONSTRAINT "consent_decisions_state_known" CHECK ("state" IN ('granted', 'revoked')),
    ADD CONSTRAINT "consent_decisions_policy_version_not_blank" CHECK (char_length("policy_version") > 0),
    ADD CONSTRAINT "consent_decisions_decided_time_zone_valid" CHECK (flowwave_is_valid_time_zone("decided_time_zone")),
    ADD CONSTRAINT "consent_decisions_decided_offset_range" CHECK ("decided_utc_offset_minutes" BETWEEN -840 AND 840),
    -- Prisma creates list columns without NOT NULL.
    ADD CONSTRAINT "consent_decisions_scopes_not_null" CHECK ("scopes" IS NOT NULL),
    ADD CONSTRAINT "consent_decisions_scopes_match_state" CHECK (
        ("state" = 'granted' AND cardinality("scopes") > 0 AND "scopes" <@ ARRAY['sleep_duration']::text[])
        OR ("state" = 'revoked' AND cardinality("scopes") = 0)
    );

CREATE FUNCTION consent_decisions_forbid_update() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
    RAISE EXCEPTION 'consent_decisions is append-only; insert a new decision instead'
        USING ERRCODE = 'restrict_violation';
END;
$$;

CREATE TRIGGER consent_decisions_append_only
    BEFORE UPDATE ON "consent_decisions"
    FOR EACH ROW EXECUTE FUNCTION consent_decisions_forbid_update();

