ALTER TABLE "health_data_sources"
    ADD CONSTRAINT "health_data_sources_source_key_matches_kind" CHECK (
        "source_key" = "kind"::text OR "source_key" LIKE "kind"::text || ':_%'
    ),
    ADD CONSTRAINT "health_data_sources_provider_package_format" CHECK (
        "provider_package" IS NULL
        OR "provider_package" ~ '^[A-Za-z][A-Za-z0-9_]*(\.[A-Za-z][A-Za-z0-9_]*)+$'
    ),
    ADD CONSTRAINT "health_data_sources_manual_has_no_provider" CHECK (
        "kind" <> 'manual_entry' OR "provider_package" IS NULL
    ),
    ADD CONSTRAINT "health_data_sources_device_type_known" CHECK (
        "recording_device_type" IS NULL OR "recording_device_type" IN
            ('unknown', 'watch', 'phone', 'scale', 'ring', 'head_mounted', 'fitness_band', 'chest_strap', 'smart_display')
    ),
    ADD CONSTRAINT "health_data_sources_names_not_blank" CHECK (
        ("provider_name" IS NULL OR char_length("provider_name") > 0)
        AND ("recording_device_manufacturer" IS NULL OR char_length("recording_device_manufacturer") > 0)
        AND ("recording_device_model" IS NULL OR char_length("recording_device_model") > 0)
    );

-- health_samples ------------------------------------------------------------
ALTER TABLE "health_samples"
    ADD CONSTRAINT "health_samples_start_time_zone_valid" CHECK (flowwave_is_valid_time_zone("start_time_zone")),
    ADD CONSTRAINT "health_samples_end_time_zone_valid" CHECK (flowwave_is_valid_time_zone("end_time_zone")),
    ADD CONSTRAINT "health_samples_offsets_range" CHECK (
        "start_utc_offset_minutes" BETWEEN -840 AND 840 AND "end_utc_offset_minutes" BETWEEN -840 AND 840
    ),
    ADD CONSTRAINT "health_samples_metric_unit" CHECK (
        ("metric" = 'steps' AND "unit" = 'count')
        OR ("metric" IN ('heart_rate', 'resting_heart_rate') AND "unit" = 'beats_per_minute')
    ),
    -- Aggregation windows from docs/architecture/data-flow.md.
    ADD CONSTRAINT "health_samples_interval_per_metric" CHECK (
        ("metric" = 'steps' AND "end_at_utc" - "start_at_utc" = interval '1 hour')
        OR ("metric" = 'heart_rate' AND "end_at_utc" - "start_at_utc" = interval '5 minutes')
        OR ("metric" = 'resting_heart_rate' AND "end_at_utc" > "start_at_utc"
            AND "end_at_utc" - "start_at_utc" <= interval '1 day')
    ),
    ADD CONSTRAINT "health_samples_value_present_xor_missing" CHECK (
        ("value" IS NULL) <> ("value_missing_reason" IS NULL)
    ),
    ADD CONSTRAINT "health_samples_value_range" CHECK (
        "value" IS NULL
        OR ("metric" = 'steps' AND "value" BETWEEN 0 AND 100000 AND "value" = trunc("value"))
        OR ("metric" IN ('heart_rate', 'resting_heart_rate') AND "value" BETWEEN 20 AND 250)
    ),
    ADD CONSTRAINT "health_samples_heart_rate_range_columns" CHECK (
        ("metric" = 'heart_rate' AND "value" IS NOT NULL
            AND "min_value" IS NOT NULL AND "max_value" IS NOT NULL
            AND "min_value" BETWEEN 20 AND 250 AND "max_value" BETWEEN 20 AND 250
            AND "min_value" <= "value" AND "value" <= "max_value")
        OR ("min_value" IS NULL AND "max_value" IS NULL
            AND NOT ("metric" = 'heart_rate' AND "value" IS NOT NULL))
    ),
    ADD CONSTRAINT "health_samples_sample_count" CHECK (
        "sample_count" IS NULL OR ("sample_count" >= 1 AND "value" IS NOT NULL)
    ),
    ADD CONSTRAINT "health_samples_keys_not_blank" CHECK (
        char_length("idempotency_key") > 0 AND ("source_record_id" IS NULL OR char_length("source_record_id") > 0)
    );

-- sleep_sessions ------------------------------------------------------------
ALTER TABLE "sleep_sessions"
    ADD CONSTRAINT "sleep_sessions_start_time_zone_valid" CHECK (flowwave_is_valid_time_zone("start_time_zone")),
    ADD CONSTRAINT "sleep_sessions_end_time_zone_valid" CHECK (flowwave_is_valid_time_zone("end_time_zone")),
    ADD CONSTRAINT "sleep_sessions_offsets_range" CHECK (
        "start_utc_offset_minutes" BETWEEN -840 AND 840 AND "end_utc_offset_minutes" BETWEEN -840 AND 840
    ),
    ADD CONSTRAINT "sleep_sessions_interval" CHECK (
        "end_at_utc" > "start_at_utc" AND "end_at_utc" - "start_at_utc" <= interval '24 hours'
    ),
    ADD CONSTRAINT "sleep_sessions_stage_ranges" CHECK (
        ("deep_sleep_minutes" IS NULL OR "deep_sleep_minutes" BETWEEN 0 AND 1440)
        AND ("light_sleep_minutes" IS NULL OR "light_sleep_minutes" BETWEEN 0 AND 1440)
        AND ("rem_sleep_minutes" IS NULL OR "rem_sleep_minutes" BETWEEN 0 AND 1440)
        AND ("awake_minutes" IS NULL OR "awake_minutes" BETWEEN 0 AND 1440)
    ),
    ADD CONSTRAINT "sleep_sessions_stages_fit_session" CHECK (
        COALESCE("deep_sleep_minutes", 0) + COALESCE("light_sleep_minutes", 0)
        + COALESCE("rem_sleep_minutes", 0) + COALESCE("awake_minutes", 0)
        <= ceil(extract(epoch FROM "end_at_utc" - "start_at_utc") / 60)
    ),
    ADD CONSTRAINT "sleep_sessions_stages_present_xor_missing" CHECK (
        ("deep_sleep_minutes" IS NULL AND "light_sleep_minutes" IS NULL
            AND "rem_sleep_minutes" IS NULL AND "awake_minutes" IS NULL)
        = ("stages_missing_reason" IS NOT NULL)
    ),
    ADD CONSTRAINT "sleep_sessions_version_positive" CHECK ("version" >= 1),
    ADD CONSTRAINT "sleep_sessions_keys_not_blank" CHECK (
        char_length("idempotency_key") > 0 AND ("source_record_id" IS NULL OR char_length("source_record_id") > 0)
    );

