-- device_usage_buckets ------------------------------------------------------
ALTER TABLE "device_usage_buckets"
    ADD CONSTRAINT "device_usage_buckets_time_zone_valid" CHECK (flowwave_is_valid_time_zone("bucket_start_time_zone")),
    ADD CONSTRAINT "device_usage_buckets_offset_range" CHECK ("bucket_start_utc_offset_minutes" BETWEEN -840 AND 840),
    ADD CONSTRAINT "device_usage_buckets_duration" CHECK ("bucket_duration_minutes" = 30),
    ADD CONSTRAINT "device_usage_buckets_aligned" CHECK (
        extract(epoch FROM "bucket_start_at_utc")::bigint % 1800 = 0
    ),
    ADD CONSTRAINT "device_usage_buckets_present_xor_missing" CHECK (
        ("missing_reason" IS NOT NULL
            AND "screen_on_seconds" IS NULL AND "unlock_count" IS NULL AND "app_switch_count" IS NULL
            AND "productivity_seconds" IS NULL AND "communication_seconds" IS NULL AND "social_seconds" IS NULL
            AND "entertainment_seconds" IS NULL AND "games_seconds" IS NULL AND "information_seconds" IS NULL
            AND "other_seconds" IS NULL)
        OR ("missing_reason" IS NULL
            AND "screen_on_seconds" IS NOT NULL AND "unlock_count" IS NOT NULL AND "app_switch_count" IS NOT NULL
            AND "productivity_seconds" IS NOT NULL AND "communication_seconds" IS NOT NULL AND "social_seconds" IS NOT NULL
            AND "entertainment_seconds" IS NOT NULL AND "games_seconds" IS NOT NULL AND "information_seconds" IS NOT NULL
            AND "other_seconds" IS NOT NULL)
    ),
    ADD CONSTRAINT "device_usage_buckets_ranges" CHECK (
        "missing_reason" IS NOT NULL
        OR ("screen_on_seconds" BETWEEN 0 AND 1800
            AND "unlock_count" BETWEEN 0 AND 1800
            AND "app_switch_count" BETWEEN 0 AND 1800
            AND "productivity_seconds" BETWEEN 0 AND 1800
            AND "communication_seconds" BETWEEN 0 AND 1800
            AND "social_seconds" BETWEEN 0 AND 1800
            AND "entertainment_seconds" BETWEEN 0 AND 1800
            AND "games_seconds" BETWEEN 0 AND 1800
            AND "information_seconds" BETWEEN 0 AND 1800
            AND "other_seconds" BETWEEN 0 AND 1800
            AND "productivity_seconds" + "communication_seconds" + "social_seconds" + "entertainment_seconds"
                + "games_seconds" + "information_seconds" + "other_seconds" <= "screen_on_seconds")
    ),
    ADD CONSTRAINT "device_usage_buckets_key_not_blank" CHECK (char_length("idempotency_key") > 0);

