-- The only permitted change is the foreign key setting user_id to NULL when
-- the user is deleted.
CREATE FUNCTION audit_events_forbid_update() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
    IF OLD.user_id IS NOT NULL AND NEW.user_id IS NULL
       AND (to_jsonb(NEW) - 'user_id') = (to_jsonb(OLD) - 'user_id') THEN
        RETURN NEW;
    END IF;
    RAISE EXCEPTION 'audit_events is append-only'
        USING ERRCODE = 'restrict_violation';
END;
$$;

CREATE TRIGGER audit_events_append_only
    BEFORE UPDATE ON "audit_events"
    FOR EACH ROW EXECUTE FUNCTION audit_events_forbid_update();

-- updated_at_utc is maintained by the database, including for raw SQL updates.
DO $$
DECLARE
    table_name text;
BEGIN
    FOR table_name IN
        SELECT c.table_name FROM information_schema.columns c
        WHERE c.table_schema = current_schema() AND c.column_name = 'updated_at_utc'
        ORDER BY c.table_name
    LOOP
        EXECUTE format(
            'CREATE TRIGGER %I BEFORE UPDATE ON %I FOR EACH ROW EXECUTE FUNCTION flowwave_set_updated_at()',
            table_name || '_set_updated_at', table_name
        );
    END LOOP;
END;
$$;
